type SyntaxError struct {
	Message  string
	Location *Location
	Level    SyntaxErrorLevel
	Type     SyntaxErrorType
}

func NewSyntaxError(
	message string,
	location *Location,
	level SyntaxErrorLevel,
	errType SyntaxErrorType,
) *SyntaxError {
	return &SyntaxError{
		Message:  message,
		Location: location,
		Level:    level,
		Type:     errType,
	}
}
